import os, re, shutil, subprocess, zipfile
from pathlib import Path
from xml.etree import ElementTree as ET

SRC = Path('/root/papers/all')
DEST = Path('/root/papers')

CATS = {
    'LLM': [
        ('large language model', 6), ('language model', 4), ('transformer', 3),
        ('attention mechanism', 3), ('self-attention', 3), ('prompt', 3),
        ('in-context', 3), ('few-shot', 2), ('chain-of-thought', 3),
        ('retrieval augmented', 3), ('rag', 2), ('fine-tun', 2), ('pretrain', 2),
        ('rlhf', 4), ('instruction tuning', 3), ('chatgpt', 4), ('gpt-', 3),
        ('bert', 2), ('tokenizer', 2), ('tokens', 1),
    ],
    'trapped_ion_and_qc': [
        ('trapped ion', 7), ('ion trap', 6), ('paul trap', 4), ('lamb-dicke', 4),
        ('mølmer-sørensen', 4), ('molmer-sorensen', 4), ('sideband', 3),
        ('laser cooling', 3), ('phonon', 2),
        ('quantum computing', 5), ('quantum computer', 5), ('quantum information', 3),
        ('qubit', 4), ('quantum gate', 3), ('quantum circuit', 3),
        ('error correction', 3), ('fault-tolerant', 3), ('surface code', 3),
        ('stabilizer', 2), ('entanglement', 2),
    ],
    'black_hole': [
        ('black hole', 8), ('event horizon', 5), ('hawking', 3), ('kerr', 3),
        ('schwarzschild', 3), ('accretion', 3), ('singularity', 2),
        ('bekenstein', 2), ('gravitational lens', 2), ('quasar', 2), ('agn', 2),
        ('sgr a', 4), ('sgr a*', 4), ('m87', 3), ('eht', 2),
    ],
    'DNA': [
        ('dna', 8), ('deoxyribonucle', 5), ('genome', 5), ('genomic', 5),
        ('sequenc', 4), ('nucleotide', 3), ('chromosome', 3), ('gene', 2),
        ('crispr', 4), ('rna', 2), ('double helix', 4), ('polymerase', 2),
    ],
    'music_history': [
        ('music', 5), ('musicology', 5), ('composer', 3), ('song', 3),
        ('lyrics', 3), ('billboard', 4), ('genre', 2), ('melody', 2),
        ('harmony', 2), ('jazz', 3), ('baroque', 3), ('renaissance', 3),
        ('classical', 2), ('romantic', 2), ('opera', 2), ('symphony', 2),
        ('popular music', 4),
    ],
}

# quick helpers
_ws_re = re.compile(r'\s+')

def _norm(s: str) -> str:
    return _ws_re.sub(' ', s.lower())

def extract_text(p: Path) -> str:
    suf = p.suffix.lower()
    if suf == '.pdf':
        try:
            cp = subprocess.run(
                ['pdftotext', '-f', '1', '-l', '2', '-nopgbrk', '-q', str(p), '-'],
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                timeout=20,
            )
            return _norm(cp.stdout.decode('utf-8', 'ignore'))
        except Exception:
            return ''
    if suf in ('.docx', '.pptx'):
        try:
            with zipfile.ZipFile(p) as z:
                if suf == '.docx':
                    xml = z.read('word/document.xml')
                    root = ET.fromstring(xml)
                    parts = [el.text for el in root.iter() if el.tag.endswith('}t') and el.text]
                    return _norm(' '.join(parts))
                else:
                    slides = sorted(n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml'))
                    parts = []
                    for n in slides[:3]:
                        root = ET.fromstring(z.read(n))
                        parts += [el.text for el in root.iter() if el.tag.endswith('}t') and el.text]
                    return _norm(' '.join(parts))
        except Exception:
            return ''

    # fallback: try plain text
    try:
        data = p.read_bytes()[:20000]
        return _norm(data.decode('utf-8', 'ignore'))
    except Exception:
        return ''

def score(text: str, cat: str) -> float:
    total = 0.0
    for kw, w in CATS[cat]:
        if kw in text:
            total += float(w)
    return total

def choose_cat(text: str) -> str:
    scores = {cat: score(text, cat) for cat in CATS}
    best_cat, best_score = max(scores.items(), key=lambda kv: kv[1])
    if best_score <= 0:
        return 'music_history'

    # tie-breakers for common ambiguities
    # If a document mentions both 'quantum' terms and 'black hole', black_hole should win.
    if scores['black_hole'] >= 8 and best_cat != 'black_hole':
        return 'black_hole'
    if scores['DNA'] >= 8 and best_cat != 'DNA':
        return 'DNA'
    if scores['LLM'] >= 6 and best_cat != 'LLM':
        return 'LLM'

    return best_cat

files = sorted([p for p in SRC.iterdir() if p.is_file()])
if not files:
    raise SystemExit('No files found in /root/papers/all')

moved = {k: 0 for k in CATS}
assignments = []

for p in files:
    txt = extract_text(p)
    cat = choose_cat(txt)
    dest_dir = DEST / cat
    dest = dest_dir / p.name
    if dest.exists():
        raise SystemExit(f'Name collision: {dest} already exists')
    shutil.move(str(p), str(dest))
    moved[cat] += 1
    assignments.append((p.name, cat))

print('Moved counts by folder:')
for k in ['LLM', 'trapped_ion_and_qc', 'black_hole', 'DNA', 'music_history']:
    print(f'  {k}: {moved[k]}')
print(f'Total moved: {sum(moved.values())}')
