import re, shutil, subprocess, zipfile
from pathlib import Path
from xml.etree import ElementTree as ET

BASE = Path('/root/papers')
FOLDERS = ['LLM','trapped_ion_and_qc','black_hole','DNA','music_history']

_ws = re.compile(r'\s+')

def norm(s: str) -> str:
    return _ws.sub(' ', s.lower())

def extract(p: Path) -> str:
    suf = p.suffix.lower()
    if suf == '.pdf':
        cp = subprocess.run(
            ['pdftotext','-f','1','-l','2','-nopgbrk','-q',str(p),'-'],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=20,
        )
        return norm(cp.stdout.decode('utf-8','ignore'))
    if suf == '.docx':
        with zipfile.ZipFile(p) as z:
            root = ET.fromstring(z.read('word/document.xml'))
            parts = [el.text for el in root.iter() if el.tag.endswith('}t') and el.text]
        return norm(' '.join(parts))
    if suf == '.pptx':
        with zipfile.ZipFile(p) as z:
            slides = sorted(n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml'))
            parts = []
            for n in slides[:3]:
                root = ET.fromstring(z.read(n))
                parts += [el.text for el in root.iter() if el.tag.endswith('}t') and el.text]
        return norm(' '.join(parts))
    try:
        return norm(p.read_text(errors='ignore')[:50000])
    except Exception:
        return ''

BH = [r'\bblack hole\b', r'\bevent horizon\b', r'\bschwarzschild\b', r'\bkerr\b', r'\bhawking\b']
QC = [r'\btrapped ion\b', r'\bion trap\b', r'\bpaul trap\b', r'\blamb-?dicke\b', r'\bqubit\b', r'\bquantum computing\b', r'\bquantum computer\b', r'\bquantum gate\b', r'\bquantum circuit\b', r'\bquantum information\b']
LLM_STRONG = [r'\blarge language model\b', r'\bllm\b', r'\btransformer\b', r'\bgpt\b', r'\bchatgpt\b', r'\brlhf\b', r'\binstruction tuning\b', r'\bfoundation model\b', r'\bbert\b']
MUSIC = [r'\bmusic\b', r'\bmusicology\b', r'\bbillboard\b', r'\blyrics\b', r'\bcomposer\b', r'\bjazz\b', r'\bopera\b', r'\bsymphon\w*\b', r'\bpopular music\b', r'\bgenre\b', r'\bsong\b']

DNA_TOKEN = ***REDACTED***'\bdna\b'
DNA_CONTEXT = r'\b(genome|genomic|sequenc\w*|nucleotide\w*|chromosome\w*|gene\w*|crispr|rna|protein\w*|cell\w*)\b'
DNA_STRONG = [r'\bgenome\b', r'\bgenomic\b', r'\bdeoxyribonucle\w*\b', r'\bchromosome\b', r'\bcrispr\b']

def any_re(pats, text):
    return any(re.search(p, text) for p in pats)

def classify(text: str) -> str:
    if any_re(BH, text):
        return 'black_hole'
    if any_re(QC, text):
        return 'trapped_ion_and_qc'

    dna = (re.search(DNA_TOKEN, text) and re.search(DNA_CONTEXT, text)) or any_re(DNA_STRONG, text)
    if dna:
        return 'DNA'

    if any_re(LLM_STRONG, text):
        return 'LLM'

    if any_re(MUSIC, text):
        return 'music_history'

    return 'music_history'

# gather all files
all_files = []
for f in FOLDERS:
    for p in (BASE/f).iterdir():
        if p.is_file():
            all_files.append(p)

moves = []
for p in sorted(all_files):
    cur = p.parent.name
    txt = extract(p)
    new = classify(txt)
    if new != cur:
        dest = BASE/new/p.name
        if dest.exists():
            raise SystemExit(f'Collision moving {p} -> {dest}')
        moves.append((p, dest))

for src, dst in moves:
    shutil.move(str(src), str(dst))

print(f'Adjusted placements: {len(moves)}')
for src, dst in moves[:30]:
    print(f'  {src.parent.name} -> {dst.parent.name}: {src.name}')
if len(moves) > 30:
    print('  ...')

# final counts
print('Final counts:')
for f in FOLDERS:
    c = sum(1 for p in (BASE/f).iterdir() if p.is_file())
    print(f'  {f}: {c}')
print('Total:', sum(sum(1 for p in (BASE/f).iterdir() if p.is_file()) for f in FOLDERS))
PY"}

